type Concept = readonly [concept: string, description: RegExp];
type Query = readonly [asked: RegExp, answer: string, explanation: RegExp];
export type ReviewedGroup = { queries: readonly Query[]; concepts: readonly Concept[] };

function group(concepts: readonly Concept[], queries: readonly Query[]): ReviewedGroup {
  return { concepts, queries };
}

